import java.util.*;

public class Main {
    int addDigits(int num) {
        while (num >= 10) {              // keep folding as long as more than one digit remains
            int digitSum = 0;
            int temp = num;
            while (temp > 0) {
                digitSum += temp % 10;     // peel off the last digit and add it in
                temp /= 10;                  // drop that digit and look at what's left
            }
            num = digitSum;                 // replace num with the sum of its digits
        }
        return num;                        // single digit remains
    }

    public static void main(String[] args) {
        int num = 38;
        Main solution = new Main();
        System.out.println(solution.addDigits(num));
    }
}

